"""Informes reproducibles con evidencia versionada, sin afirmar despliegues pendientes."""
import json
from pathlib import Path
from reportlab.lib import colors
from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
from reportlab.lib.pagesizes import A4
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle, Image, PageBreak

ROOT=Path(__file__).resolve().parents[1]
E=ROOT/'docs/evidencias/validacion-2026-11-19'
curves=json.loads((E/'survival_curves.json').read_text())
C=ROOT/'docs/evidencias/jenkins-candidate-2-2026-11-19'
bench=json.loads((C/'load_balancing.json').read_text())
styles=getSampleStyleSheet()
styles.add(ParagraphStyle(name='BodyES',fontName='Helvetica',fontSize=10,leading=14,spaceAfter=8))
styles['Title'].textColor=colors.HexColor('#183c55')
styles['Heading2'].textColor=colors.HexColor('#183c55')

def p(s): return Paragraph(s,styles['BodyES'])
def title(s): return Paragraph(s,styles['Title'])
def h(s): return Paragraph(s,styles['Heading2'])
def table(headers,rows):
    data=[[p(str(x)) for x in headers]]+[[p(str(x)) for x in r] for r in rows]
    t=Table(data,repeatRows=1,hAlign='LEFT')
    t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#e5eef4')),('VALIGN',(0,0),(-1,-1),'TOP'),('LINEBELOW',(0,0),(-1,0),.7,colors.HexColor('#183c55')),('BOTTOMPADDING',(0,0),(-1,-1),5)]))
    return t

def pic(name,w=475,hgt=267):return Image(str(ROOT/'docs/figuras'/name),width=w,height=hgt)
def footer(canvas,doc):
    canvas.setFont('Helvetica',8);canvas.setFillColor(colors.HexColor('#52616b'))
    canvas.drawString(42,24,'LifeMap | Andrés y Julián | Validación técnica, 19 nov 2026 | Despliegue final pendiente')
    canvas.drawRightString(A4[0]-42,24,str(doc.page))
def build(name,pages):
    (ROOT/'output/pdf').mkdir(parents=True, exist_ok=True)
    story=[]
    for i,page in enumerate(pages):
        if i:story.append(PageBreak())
        story.extend(page)
    SimpleDocTemplate(str(ROOT/'output/pdf'/name),pagesize=A4,rightMargin=42,leftMargin=42,topMargin=40,bottomMargin=42,title=name.removesuffix('.pdf').replace('_',' '),author='LifeMap - Andrés y Julián').build(story,onFirstPage=footer,onLaterPages=footer)

common='Fuente: API pública de LifeMap, evidencia del 19/11/2026; resultados y configuraciones versionados en docs/evidencias/. Las mediciones del candidato no sustituyen la verificación de la URL final.'
E1=[]
E1.append([title('LifeMap · Entrega 1'),p('Informe técnico de validación | Big Data 2026-2 | Andrés y Julián'),h('1. Arquitectura y alcance'),p('Philadelphia, familia Restaurants. Kaggle API descarga Yelp; Dask lee y limpia por particiones; MongoDB conserva negocios GeoJSON e índice 2dsphere; Spark construye vida, modelos y tasas; Flask expone consultas; Jenkins integra las versiones. Compose incluye maestro Spark y dos workers, scheduler Dask y dos workers, MongoDB, API, Kafka KRaft y Jenkins.'),p('Servidor: Azure, Standard B4s v2, 4 vCPU y 16 GiB. URL: http://lifemap-iue.mexicocentral.cloudapp.azure.com. La evidencia pública muestra commit ab0ffb2 y todos los servicios en estado ok. El candidato E2 se valida aparte; aún no se ha promovido.'),h('2. Limpieza y volumen'),table(['Proceso','Antes','Después'],[['Negocios originales','150.346','150.346'],['Filtro metropolitano','150.346','37.212'],['Categorías presentes','37.212','37.179'],['Familia Restaurants','37.179','13.883'],['Reseñas del área/familia','6.990.280','1.166.192']]),p('Se descartaron 113.134 negocios fuera del área, 33 sin categorías y 23.296 fuera de la familia. No se observaron descartes por coordenadas inválidas, is_open inválido o IDs duplicados en esta ejecución. Entre las reseñas del alcance no hubo descartes por texto, estrellas, fecha o duplicados. Se procesa todo el alcance y se supera un millón de reseñas.'),p('Las reglas eliminan ubicaciones no consultables, textos sin señal y registros que duplicarían eventos o exposición. Los conteos completos por regla se conservan en resultados-vm-2026-11-19.md.'),p(common)])
E1.append([title('Modelo de sentimiento'),p('Pipeline en inglés: limpieza, RegexTokenizer, StopWordsRemover conservando negaciones, HashingTF/IDF y clasificación. Se comparan Naive Bayes multinomial y regresión logística; el negocio completo permanece en un único conjunto. Las reseñas posteriores al día T=2020-06-30 se reservan para streaming.'),table(['Modelo / clase','Precision','Recall','F1'],[['NB negativo','.7169','.7383','.7274'],['NB neutral','.3601','.5342','.4302'],['NB positivo','.9306','.8348','.8801'],['LR negativo','.8036','.8097','.8066'],['LR neutral','.5007','.3207','.3910'],['LR positivo','.8902','.9503','.9193']]),p('F1 macro: NB=0,6792; LR=0,7056. Accuracy: NB=0,7762; LR=0,8402. El modelo registrado seleccionado es LR, versión v20261102-155756. La comparación usa el conjunto de prueba del entrenamiento existente; para futuras búsquedas de hiperparámetros debe reservarse validación independiente.'),h('Matrices de confusión'),p('Orden de filas y columnas: negativo, neutral, positivo.'),table(['Real','NB: predicciones','LR: predicciones'],[['Negativo','32.230 / 9.629 / 1.797','35.347 / 4.099 / 4.210'],['Neutral','5.857 / 14.946 / 7.174','6.330 / 8.972 / 12.675'],['Positivo','6.870 / 16.932 / 120.235','2.310 / 4.848 / 136.879']]),p('Distribución total: 244.537 negativas, 149.159 neutrales y 772.496 positivas. La mayoría positiva hace insuficiente accuracy como criterio. LR mejora F1 negativo y positivo, pero reduce recall neutral; no debe interpretarse la exactitud global como buen desempeño uniforme en las tres clases.'),p(common)])
E1.append([title('Vida y tasas de cierre'),p('business_days = última reseña - primera reseña + 1. Evento: is_open=0; censurado: is_open=1. Para supervivencia, la duración de abiertos se extiende hasta el corte del dataset, 2022-01-19, en un campo analítico separado. La primera y última reseña son aproximaciones, no fechas reales de apertura y cierre.'),table(['Indicador','Valor'],[['Negocios','13.883'],['Cierres observados','4.956'],['Abiertos / censurados','8.927'],['Entrada anterior a OBS_START','4.105'],['Días-negocio','35.359.777'],['Mediana del intervalo de reseñas','2.416 días']]),h('MapReduce y exposición'),p('Cada negocio emite (categoría o geohash, (evento, días-negocio)); reduceByKey suma ambos componentes. Se verifica igualdad clave por clave contra groupBy de DataFrames. Tasa anualizada (%) = cierres / (días-negocio / 365) × 100. No es una proporción simple de negocios cerrados.'),p('Umbral mínimo: 18.250 días-negocio (50 años-negocio), configurable en /stats/closure. Los intervalos exactos de Poisson acompañan las tasas y muestran que incluso grupos aceptados pueden ser imprecisos.'),table(['Categoría','Tasa anual %','IC 95%'],[['Falafel','16,632','7,605 - 31,573'],['Buffets','13,389','9,565 - 18,232'],['Cajun/Creole','13,027','7,957 - 20,119'],['Indian','11,033','8,721 - 13,769']]),p('Consultas: /businesses/near usa $near; /businesses/within, $geoWithin; /zones/summary, $geoNear. Se agregan /health, /stats/closure y /predict, con parámetros variables y errores de validación. Los resultados agregados no establecen causalidad entre sentimiento y cierre.'),p(common)])
E1.append([title('Balanceo, CI y limitaciones'),p('Validación corregida: MapReduce de cierres y días-negocio sobre 13.883 negocios, 2/8/32/200 particiones, tres repeticiones por estrategia, calentamiento separado y AQE desactivado. Ejecución Jenkins candidata 2, commit 0b30d84: maestro y dos workers Spark, cuatro cores declarados para batch, ejecutores de 1 GiB, junto al consumidor activo. La VM tiene cuatro vCPU compartidas por todos los servicios.'),pic('benchmark_cluster.png',475,245),table(['Particiones','Sin clave: media ± DE (s)','Por categoría: media ± DE (s)'],[[n,*[f"{next(r for r in bench['timings'] if r['partitions']==n and r['strategy']==s)['mean_s']:.3f} ± {next(r for r in bench['timings'] if r['partitions']==n and r['strategy']==s)['std_s']:.3f}" for s in ('sin clave','con clave: main_category')]] for n in (2,8,32,200)]),p('En esta carga pequeña, 200 particiones aumentan el sobrecosto. Los conteos de filas por partición para ciudad, categoría y reparto sin clave se guardan en load_balancing.json; los tiempos no deben extrapolarse a datasets o recursos diferentes.'),p('Jenkins usa pollSCM cada dos minutos. El candidato añade imágenes por commit, copia aislada de datos/modelos, pruebas unitarias, API y streaming antes de promoción. Se verificaron 55 pruebas sobre el candidato en la VM; el build completo y la promoción siguen pendientes.'),p('Cierre de E1: incorporar evidencia de build bloqueado y modificación en vivo. La disponibilidad continua durante la ventana de evaluación y el dominio de ambos integrantes se comprueban en sustentación.')])
build('lifemap_entrega1_validacion.pdf',E1)

G=next(c for c in curves if c['group_type']=='global' and c['group']=='todos')
E2=[]
E2.append([title('LifeMap · Entrega 2'),p('Informe técnico de validación | Plataforma acumulativa de E1 y E2'),h('1. Arquitectura completa'),p('Se conserva la misma API y MongoDB. Kafka KRaft recibe reviews en tres particiones, con business_id como clave. Structured Streaming carga el modelo persistido de sentimiento y el de riesgo una vez, clasifica reseñas, mantiene ventanas y genera alertas. Power BI debe consultar las tablas expuestas por la API.'),p('Fuentes históricas: 13.883 negocios y 1.166.192 reseñas de Philadelphia/Restaurants. T=2020-06-30; entrenamiento usa instantes anteriores a 2020-07-01 00:00 UTC y streaming parte de ese límite. El corte final observado es 2022-01-19.'),h('2. Reproducción temporal'),p('El productor ordena por fecha e ID, valida velocidad positiva y límites temporales, conserva IDs y fechas del evento y comprueba confirmaciones de Kafka. Configuración de demo: treinta días históricos cada diez segundos reales. Kafka preserva orden por partición; el consumidor no presupone orden global de llegada.'),h('Estado de verificación'),p('El código y sus pruebas están en ramas de trabajo publicadas. La API de referencia sigue en ab0ffb2. Este informe documenta validaciones y modelos existentes; no certifica todavía la promoción del candidato, el dashboard Power BI ni la sustentación.'),p('La fecha normativa de E2 es 24 de noviembre de 2026. Se prioriza la guía frente a las fechas contradictorias de las diapositivas. Debe mantenerse la URL al menos desde 48 horas antes de la sustentación.'),p(common)])
E2.append([title('Inferencia, ventanas y alertas'),h('3. Inferencia sin reentrenar'),p('Cada mensaje válido genera clase, probabilidades, modelo y fecha de proceso. MongoDB usa review_id como ID estable. El consumidor valida compatibilidad entre la versión de sentimiento, la versión de riesgo y T. /health informa offsets, retraso y una señal periódica de actividad del consumidor.'),h('4. Idempotencia y riesgo por micro-lote'),p('risk_features guarda el estado histórico hasta T. Para cada negocio afectado se reconstruye risk_state a partir de esa base y reseñas únicas persistidas. Luego se calculan las variables y se actualizan risk_scores y alerts. Reintentar después de una escritura parcial no suma otra vez las reseñas; el estado inicial permanece inmutable.'),h('5. Ventanas geoespaciales'),p('Ventanas de treinta días por geohash sobre event_time derivado de date; watermark de siete días. La deduplicación usa ID y fecha del evento. El modo append publica ventanas cerradas después del watermark. El cierre depende del avance del tiempo del evento, no del reloj real; las ventanas finales pueden quedar abiertas al terminar el histórico.'),p('Hotspot: incremento de al menos diez puntos porcentuales frente a la ventana inmediatamente anterior y al menos quince reseñas en ambas. Se guardan geometría, centro, conteos, porcentajes y delta. Primero se escriben los conteos del lote y luego se actualizan comparaciones para evitar leer una predecesora desactualizada.'),p('Con quince reseñas, una reseña representa aproximadamente 6,7 puntos; exigir diez reduce la sensibilidad a una sola reseña, aunque no constituye una prueba estadística de significancia. Revisar estabilidad de la regla con datos reales.'),h('API'),p('/live/hotspots consulta ventana y radio; /alerts admite radio o polígono; /survival/&lt;categoria&gt; expone curvas y tamaño en riesgo; /risk/near consulta probabilidades cercanas. Se conservan los seis endpoints de E1.')])
E2.append([title('Supervivencia y censura'),p('Kaplan-Meier estima supervivencia desde la primera reseña. Se considera evento el cierre observado; abiertos permanecen censurados hasta el corte del dataset. OBS_START=2010-01-01 define entrada tardía. Negocios cerrados antes de esa ventana no estuvieron en riesgo dentro del estudio.'),pic('km_global.png',475,255),p('Resultado corregido: 316 curvas por categoría, zona y global; 83 superan n>=30 y eventos>=10. Global ajustada: n=13.789, eventos=4.862, censurados=8.927, mediana=14,36 años. Sin corrección: n=13.883, mediana=14,79 años. La comparación incluye el efecto de excluir 94 cierres anteriores a la ventana; no es una estimación causal.'),table(['Tiempo observado (años)','Negocios en riesgo','Supervivencia'],[[f"{r['t_years']:.2f}",r['at_risk'],f"{r['survival']:.4f}"] for r in [min(G['curve'],key=lambda r:abs(r['t_years']-t)) for t in (0,5,10,15)]]),p('S(1 año)=0,9463; S(5 años)=0,7514; S(10 años)=0,5987. El número en riesgo disminuye en la cola; no conviene interpretar pequeños cambios finales como diferencias robustas. Los intervalos y todos los puntos se conservan en survival_curves.json.')])
E2.append([title('Comparaciones por categoría y zona'),pic('km_category.png',475,240),pic('km_zone.png',475,240),p('Se muestran cinco grupos grandes de cada tipo. Las zonas se construyen como una rejilla 3x3 sobre los percentiles 2-98 de coordenadas; la membresía se consulta con $geoWithin. No cubren necesariamente todos los negocios del área y no equivalen a divisiones administrativas.'),p('Cada curva exporta censura, entradas, mediana cuando existe, IC y n en riesgo. La primera reseña no revela la apertura real: OBS_START corrige truncamiento de observación, pero no recupera edad previa desconocida. Por ello las medianas son de vida aproximada por reseñas.')])
E2.append([title('Modelo de riesgo de cierre'),p('Variables calculadas hasta T: sentimiento medio, pendiente mensual del porcentaje negativo en seis meses, estrellas medias, logaritmo del conteo de reseñas, edad, recencia y competidores de la misma categoría a 500 metros mediante $geoNear. No se usan estrellas/conteos finales de business.json como predictores.'),p('Etiqueta positiva: cerrado con última reseña en los doce meses calendario posteriores a T. Negativa: abierto o con actividad después del horizonte. Se excluyen negocios sin actividad después de T. La partición de negocios es estratificada 60/20/20 y el umbral se selecciona en validación maximizando F2; la elección entre LR y GBT usa AUC-PR de validación.'),h('Resultados del modelo registrado antes del candidato'),table(['Modelo','AUC-ROC','AUC-PR','Recall','Umbral'],[['LR','.6862','.1295','.4865','.5266'],['GBT','.6163','.0927','.8108','.1221']]),p('Prevalencia de prueba=0,0462. LR: precisión=0,0805 y F1=0,1382; GBT: precisión=0,0537 y F1=0,1008. Modelo registrado: LR v20261102-162020, asociado al sentimiento v20261102-155756. Estas métricas corresponden al artefacto registrado, no a un entrenamiento posterior aún no verificado.'),p('La AUC-PR de LR supera la prevalencia aproximadamente 2,8 veces, pero la precisión de alerta es baja: la mayoría de avisos necesita revisión y no confirma un cierre. GBT obtiene más recall con más falsos positivos. El desbalance hace inadecuada accuracy como métrica principal.'),p('Limitaciones: is_open es una fotografía final; última reseña aproxima cierre; selección por actividad posterior introduce una cohorte condicionada al seguimiento; T cae durante la pandemia. La densidad de competidores refleja actividad observable hasta T, no censos reales de competencia.')])
E2.append([title('Pruebas, dashboard y sustentación'),h('6. Verificación'),p('El candidato pasó 55 pruebas en un contenedor temporal de la VM. La prueba de humo publica cien reseñas reales posteriores a T en un topic exclusivo, comprueba clasificación/modelos y repite las cien para verificar idempotencia. Un evento de prueba posterior hace avanzar el watermark y valida geometría, conteos únicos y ventanas de treinta días. Los recursos de prueba se eliminan al finalizar.'),p('El Jenkinsfile pasó el validador de sintaxis. El job lifemap-candidate-review se ejecuta con VALIDATE_ONLY=true: prueba el candidato sin promover API ni streaming. Deben adjuntarse el resultado completo del build y la evidencia posterior de promoción por merge a main antes de la entrega definitiva.'),h('7. Power BI'),p('Pendiente: crear y verificar el dashboard real. Están preparadas consultas Power Query con esquema explícito para alertas, hotspots, supervivencia y evolución negativa. Se requieren mapa de hotspots, tabla de alertas activas, curvas y serie temporal conectados a la API. Las consultas no sustituyen el archivo o reporte publicado ni las capturas de actualización durante la demo.'),h('8. Reutilización y aportes'),table(['Componente de curso','Aplicación en LifeMap'],[['SentimentStream','TF-IDF y clasificación; texto real, partición por negocio y comparación NB/LR.'],['KafkaMed','Productor acelerado, inferencia y alertas; se evalúa riesgo de cierre con AUC-PR.'],['Geoespacial','Dask, GeoJSON, MongoDB, Flask, Compose y Jenkins.'],['Ejercicio de discos','reduceByKey, exposición anualizada, balanceo, watermark y censura.']]),p('Reparto de revisión: Julián, productor/riesgo/ingesta; Andrés, streaming/supervivencia/integración y pruebas. Los commits conservan su autoría real. Ambos deben explicar todo el sistema. Falta documentar referencias específicas de los repositorios previos del equipo cuando se confirme su identificación.'),p('Fuentes: guía y diapositivas LifeMap; evidencia propia versionada del 19/11/2026; Yelp Open Dataset (Kaggle); documentación de Spark Structured Streaming y lifelines. Pendientes de cierre: build completo, promoción, Power BI, disponibilidad pública continua y demo en vivo.')])
build('lifemap_entrega2_validacion.pdf',E2)
